INSERT INTO `dim_metric` (`metric`, `meaning`, `definition`, `params`, `source_table`, `version`) VALUES ('西塔停留','在西塔停下来待了一段时间','停留质心距西塔中心 ≤ 半径，且持续 ≥ 最短时长','半径 500 米；最短 30 分钟','dws_stay','v2.2.0'),
('傍晚访客','国庆当天傍晚后在西塔待过的人','有西塔停留，且该停留结束时刻 ≥ 17:00','17:00','dws_stay','v2.2.0'),
('西塔停留时长','在西塔待了多久','当天所有西塔停留时长之和；每段按首条到末条信令计','23 点后仍在者为删失，只是下限','dws_user_day','v2.2.0'),
('过夜地','凌晨待得最久的地方（不等于家）','与 0:00–6:00 重叠最长且重叠 ≥ 60 分钟的停留','60 分钟','dws_night','v2.2.0'),
('客源距离','从多远来','过夜地质心到西塔中心的直线距离','直线距离，不是路程','dws_night','v2.2.0'),
('客群标签','是哪类人','按过夜地：不明 / 市外 / 1.5 公里内为周边居民 / 其余为市内来访','1.5 公里','dws_user_day','v2.2.0'),
('客群标签（修正）','是哪类人，含当天从外地进城的人','当天第一条信令在市域外、之后进入市域，或过夜地在市外：外地来客；其余同客群标签','—','dws_user_day.segment_v2','v2.2.0'),
('出行','从一个地方到另一个地方','相邻两个停留质心相距 ≥ 500 米','500 米','dws_trip','v2.2.0'),
('商圈联动率','西塔访客还去了哪个商圈','傍晚访客中，当天在该商圈有停留的人的占比','商圈边界用 v2','dws_user_day','v2.2.0'),
('区域停留','停留发生在某个分析区域内','圆形区域看停留质心到圆心的距离 ≤ 半径；多边形区域看质心是否落在边界内；区域可以重叠','区域定义见 settings.yaml 的 areas','dws_stay_area','v2.2.0'),
('区域傍晚访客','当天傍晚后在该区域待过的人','有该区域停留，且该停留结束时刻 ≥ 17:00','17:00','dws_user_area_day','v2.2.0'),
('区域停留时长','当天在该区域待了多久','当天该区域所有停留时长之和','23 点后仍在者为删失，只是下限','dws_user_area_day','v2.2.0'),
('区域客群','是哪类人（相对某个区域）','同客群标签（修正），只是距离量到该区域的中心：1.5 公里内为周边居民；先判断、后取整','1.5 公里','dws_user_area_day','v2.2.0'),
('每小时在场人数','某小时有多少人在该区域','每人每小时一个位置（覆盖该小时 ≥ 30 分钟的停留优先，否则取信令中位位置）','少于 5 人抑制','ads_area_hourly','v2.2.0'),
('小样本抑制','对外数据里看不出个人','少于门槛的格子连同由它算出的占比一起置空并标记；同一组只藏了一格时，再藏组内最小的一格（互补抑制）','5 人','ads_各表','v2.2.0');
